<node TEXT="面试"><node TEXT="面试前" FOLDED="true"><node TEXT="背景画面"><node TEXT="干净整洁，最好书架或白墙，不要乱七八糟的东西，分散面试官注意力，或不好的印象"></node></node><node TEXT="光线"><node TEXT="灯光不要昏暗，保证能看清人"></node><node TEXT="注意不要背光（背靠窗台）"></node></node><node TEXT="穿着"><node TEXT="和线下差不多"></node></node><node TEXT="摄像头"><node TEXT="最好将摄像头架高到与视线平视的地方"></node><node TEXT="固定好位置，不要晃来晃去"></node><node TEXT="尽量多看摄像头的位置，相当于和面试官眼神交流"></node></node><node TEXT="避免被干扰"><node TEXT="闹铃，电话"></node><node TEXT="电脑的通知，弹窗"></node></node><node TEXT="肢体动作"><node TEXT="微笑，不要太严肃"></node><node TEXT="语音语调要有变化"></node></node></node><node TEXT="面试中"><node TEXT="准备阶段"><node TEXT="信息确认"></node><node TEXT="硬件设备调试"></node></node><node TEXT="必考问题"><node TEXT="自我介绍"><node TEXT="姓名"></node><node TEXT="学历"></node><node TEXT="申请岗位"></node><node TEXT="项目/学习经验"></node><node TEXT="个人评价"></node><node TEXT="注意事项"><node TEXT="时间1-2分钟"></node><node TEXT="要从口头表达，并写下来"><node TEXT="中文"><node TEXT="面试官，早上好！我叫陈杰，本科毕业于中科大数学系，现就读于香港中文大学金融工程方向。
我的研究方向是期权定价，数值算法和机器学习在量化金融上的应用。
2017.9-2019.5 我主要研究多维希尔伯特变化在障碍期权快速定价上的应用，我的算法实现比同类最快算法快20%，这项工作也在本专业顶级会议informs2018和AQFC2019做了报告。
我现在的项目是/研究新闻/对期权定价/和对冲的影响。计划引入/机器学习和深度学习的方法，实现/对极大维数期权的定价/和对新闻信息的自动化处理/并且执行相关交易/等课题。
个人是一个可以快速学习和上手新项目的研究者，同时也非常乐意去学习新的知识，我认为我可以胜任这个岗位。"></node></node><node TEXT="英文" FOLDED="true"><node TEXT="My name&apos;s CHEN Jie. I obtain my bachelor degree from University of Science and Technology of China and now I am a PhD student major in financial engineering at The Chinese University of Hong Kong."></node><node TEXT="My research mainly focuses on option pricing, numerical methods and machine learning in quantitative finance."></node><node TEXT="The last two years, I am working on developing quick numerical method for barrier option pricing using the multidimensional Hilbert transform. My algorithm beats others by 20% in speed. I have presented this work in informs2018 and AQFC2019."></node><node TEXT="Now I am researching the effect of news on option pricing and hedging. We am building models that incorporate news effect and try to apply deep learning techniques to solve it."></node><node TEXT="Besides research, I am full of enthusiasm and willing to learn new things and take challenges. To sum up, I will be a good candidate for this position."></node><node TEXT="中文"><node TEXT="面试官，早上好！我叫陈杰，本科毕业于中科大数学系，现就读于香港中文大学金融工程方向。
我的研究方向是期权定价，数值算法和机器学习在量化金融上的应用。
2017.9-2019.5 我主要研究多维希尔伯特变化在障碍期权快速定价上的应用，我的算法实现比同类最快算法快20%，这项工作也在本专业顶级会议informs2018和AQFC2019做了报告。
我现在的项目是/研究新闻/对期权定价/和对冲的影响。计划引入/机器学习和深度学习的方法，实现/对极大维数期权的定价/和对新闻信息的自动化处理/并且执行相关交易/等课题。
个人是一个可以快速学习和上手新项目的研究者，同时也非常乐意去学习新的知识，我认为我可以胜任这个岗位。"></node></node></node></node><node TEXT="练习20遍以上"></node></node></node><node TEXT="与岗位相关的经历"><node TEXT="AI课程"><node TEXT="机器学习算法及其应用"></node><node TEXT="深度学习，Pytorch框架"></node><node TEXT="强化学习"></node></node><node TEXT="金融建模"><node TEXT="熟悉常用模型和算法"></node><node TEXT="熟悉金融体系"></node></node><node TEXT="项目介绍"><node TEXT="STAR法则,即为Situation Task Action Result的缩写"></node><node TEXT="MDHT"><node TEXT="situation"><node TEXT="金融市场需要用衍生品（对冲转移风险），因此需要定价"></node><node TEXT="多维产品很流行（股票和外汇），但快速计算很难"></node><node TEXT="BM模型有问题"><node TEXT="volatility smile"><node TEXT="波动率微笑"></node></node><node TEXT="Levy 过程"><node TEXT="process with jumps"></node></node></node></node><node TEXT="task"><node TEXT="快速定价多维衍生品"></node></node><node TEXT="action"><node TEXT="基于变换的方法"><node TEXT="将定价公式映射到傅里叶空间"></node><node TEXT="将Fourier 变换转换为Hilbert 变换进行计算"></node><node TEXT="利用Sinc逼近来数值计算Hilbert变换"></node></node></node><node TEXT="result"><node TEXT="完胜蒙特卡罗模拟和有限差分方法"></node><node TEXT="比其他基于变换的方法快20%以上"></node></node></node><node TEXT="新闻相关"><node TEXT="situation"><node TEXT="新闻对股价有着很强的影响"></node></node><node TEXT="task"><node TEXT="定量研究新闻对股价和对应衍生品的冲击"></node><node TEXT="能否实现自动化交易"></node></node><node TEXT="action"><node TEXT="通过数据分析，研究股价和新闻之间的联系"><node TEXT="定性：已通过因子模型证实有强相关"></node><node TEXT="定量：试图简历新的数学模型"></node></node><node TEXT="深度强化学习"><node TEXT="学习CUHK周博磊教授的RL课程"></node><node TEXT="深度学习"><node TEXT="具有很强的特征学习能力"></node></node><node TEXT="强化学习"><node TEXT="将投资者目标和行为直接联系起来了"></node></node><node TEXT="课程大作业"><node TEXT="使用DeepRL 来实现交易策略的自动化"></node></node></node></node><node TEXT="result"></node></node></node></node><node TEXT="为什么选择公司/岗位"></node><node TEXT="性格特点"><node TEXT="1. 从宏观出发"><node TEXT="喜欢建立整体框架，再进行学习"></node></node><node TEXT="2. 坚韧"><node TEXT="对于自己感兴趣或想做的事，可以一直坚持不放弃"></node></node><node TEXT="3. 冷静"></node></node><node TEXT="行为问题"><node TEXT="遇到最困难的事"></node></node><node TEXT="注意事项"><node TEXT="时间长度"></node><node TEXT="用事实去证实自己的论点"></node><node TEXT="逻辑性要强"><node TEXT="提纲：动词+名词"></node><node TEXT="点——&gt;面，语言要精练"></node><node TEXT="否则面试官很难跟得上你的思路"></node></node><node TEXT="面试官反馈"><node TEXT="对你的兴趣和态度"><node TEXT="说话很官方，不深挖，不讨论细节，跳转话题"></node></node></node></node></node></node><node TEXT="视频模拟面试" FOLDED="true"><node TEXT="保证熟练度"></node><node TEXT="录像，反复看，会有很多无意识小动作等（摸头发，摸脸等）"></node></node><node TEXT="面试后" FOLDED="true"><node TEXT="回顾"><node TEXT="问了什么，为什么这么问"></node><node TEXT="自己的表现"><node TEXT="技术岗"><node TEXT="被拒的主要原因就是技术不过关（跟别人比起来比较弱）"></node><node TEXT="虚的原因是没有数据"><node TEXT="做一个全面的评估"></node></node></node><node TEXT="表达的问题"><node TEXT="录音"></node><node TEXT="以面试官的身份回听"></node><node TEXT="思路清楚到讲清楚需要很深的功底"></node></node></node></node><node TEXT="压力应对"></node></node><node TEXT="具体面试"><node TEXT="中信"><node TEXT="面试问题"><node TEXT="自我介绍"><node TEXT="面试官，早上好！我叫陈杰，我现在申请的量化研究员暑期实习岗位。本科毕业于中科大数学系，现就读于香港中文大学金融工程方向。
我的研究方向是期权定价，数值算法和机器学习在量化金融上的应用。
2017.9-2019.5 我主要研究多维希尔伯特变化在障碍期权快速定价上的应用，我的算法实现比同类最快算法快20%，这项工作也在本专业顶级会议informs2018和AQFC2019做了报告。"></node><node TEXT="我现在的项目是/研究新闻/对期权定价/和对冲的影响。计划引入/机器学习和深度学习的方法，实现/对极大维数期权的定价/和对新闻信息的自动化处理/并且执行相关交易/等课题。"></node><node TEXT="目前我正在学习机器学习和强化学习的课程。其中强化学习为领域大牛周博磊教授开的。计划应用这些技术到期权定价和自动化交易上。目前正在做课程大作业：使用强化学习来增强简单地配对交易算法。"></node><node TEXT="另外，我是一个可以快速学习和上手新项目的研究者，同时也非常乐意去学习新的知识。"></node></node><node TEXT="一个特长或爱好"><node TEXT="我最大的爱好是户外登山。从本科开始，我就参加了中科大的科学探险考察协会，代表协会参加由北大举办的全国大学户外技能大赛，舟山的海岛生存训练营以及青海三江源生态和人文考察，同时作为领队带领队员多次进入大别山区进行拉练活动。本科毕业后，我来到香港了，报名学习了深圳户外登山协会的领队课程并拿到领队证书，之后多次跟队和带队走遍了广东附近著名路线。"></node></node><node TEXT="券商的了解和看法"></node><node TEXT="what do you think CITIC securities do"><node TEXT="use English"></node></node></node><node TEXT="面试反馈"><node TEXT="简历要有亮点"></node></node></node><node TEXT="腾讯游戏"><node TEXT="业务问题"><node TEXT="虚拟经济"><node TEXT="怎么给游戏道具定价"></node><node TEXT="如何组合礼包"></node><node TEXT="如何自动化设置游戏指南"></node></node><node TEXT="更清晰的表述"><node TEXT="特征"><node TEXT="游戏强度，氪金强度"></node></node><node TEXT="目标"></node></node></node><node TEXT="专业问题"><node TEXT="如何防止过拟合"><node TEXT="增大数据"></node><node TEXT="加penalty"><node TEXT="+λ∥w∥2+\lambda\|w\|^2+λ∥w∥2"><node TEXT="防止参数过大"></node></node><node TEXT="+λ∥w∥+\lambda\|w\|
+λ∥w∥"><node TEXT="参数更稀疏，因为梯度在零附近不为零，还能继续下降"></node></node></node></node><node TEXT="概率问题"></node><node TEXT="极大似然估计"><node TEXT="Bayes 公式"></node><node TEXT="已知样本，反推参数"></node></node></node><node TEXT="关于工作"><node TEXT="数据，算法，工程，报告"></node></node><node TEXT="思考"><node TEXT="机器学习基础知识不过硬"></node><node TEXT="多练习实战"></node></node></node><node TEXT="MSRA"><node TEXT="AI+金融"><node TEXT="前景"><node TEXT="回答要充满信心，表达出自己的态度和兴趣"></node><node TEXT="1. 金融拥有大量结构化数据，非常适合AI应用"></node><node TEXT="2. Ai的应用可以提高服务的质量广度和节约成本"><node TEXT="反欺诈反洗钱"></node><node TEXT="小额的收费覆盖不了成本"></node></node></node><node TEXT="困难"><node TEXT="1. 金融市场极其复杂且变化极快，AI学习能力还不够快"></node><node TEXT="2. 监管，目前AI还处于黑箱状态，很难通过监管"></node><node TEXT="3. 同时懂金融和AI的人比较少"></node></node></node></node><node TEXT="字节跳动"><node TEXT="数据驱动的公司"></node></node></node><node TEXT="数据分析师"><node TEXT="获取数据"><node TEXT="提取数据"><node TEXT="需要什么数据"></node><node TEXT="沟通能力"></node></node><node TEXT="制作报表"><node TEXT="业务理解"></node><node TEXT="可视化"></node></node><node TEXT="定义指标"><node TEXT="业务与指标的映射关系"></node></node></node><node TEXT="寻找规律"><node TEXT="异动解释"><node TEXT="关联分析，维度拆解"></node></node><node TEXT="评估效果"></node><node TEXT="专项分析"><node TEXT="界定问题"></node><node TEXT="分解任务"></node><node TEXT="定量定性分析"></node></node></node><node TEXT="推动改进"><node TEXT="实验设计"></node><node TEXT="数据方案"></node><node TEXT="方向探索"></node></node></node></node>
